function validate(input) {
  const [{ Sessions = [] }] = input;
  const ids = new Set(), byUser = new Map();
  const hour = /^\d{4}-\d{2}-\d{2} \d{2}:00:00$/;
  for (const [user, start, end, id, type] of Sessions) {
    if (user === null || id === null) return 'Every session needs a user_id and a session_id.';
    if (ids.has(id)) return `session_id ${id} appears twice.`;
    ids.add(id);
    if (type !== 'Viewer' && type !== 'Streamer') return `Session ${id} must be of type Viewer or Streamer.`;
    if (!hour.test(start ?? '') || !hour.test(end ?? '')) return `Session ${id} needs times like 2023-11-01 08:00:00, on the hour.`;
    if (!(start < end)) return `Session ${id} must end after it starts.`;
    if (!byUser.has(user)) byUser.set(user, []);
    byUser.get(user).push([start, end]);
  }
  for (const [user, list] of byUser) {
    list.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
    for (let i = 1; i < list.length; i++) if (list[i][0] <= list[i - 1][1]) return `Sessions of user ${user} overlap or touch.`;
  }
  return null;
}

