function generate(rand, size) {
  const small = size === 'small';
  const users = small ? [101, 102, 103, 104] : Array.from({ length: 220 }, (_, i) => 1 + i * 3);
  const base = Date.UTC(2023, 10, 1, 0);
  const stamp = h => new Date(base + h * 3600000).toISOString().slice(0, 19).replace('T', ' ');
  const types = ['Viewer', 'Streamer'];
  const Sessions = [];
  let id = 0;
  for (const user of users) {
    const count = small ? Math.floor(rand() * 4) : 4 + Math.floor(rand() * 6);
    // Each user has a typical spacing; short spacings make qualifying pairs likely, long ones rare.
    const spread = 4 + Math.floor(rand() * (small ? 30 : 60));
    let t = Math.floor(rand() * 24);
    for (let k = 0; k < count && (small ? Sessions.length < 8 : true); k++) {
      const length = 1 + Math.floor(rand() * 3);
      Sessions.push([user, stamp(t), stamp(t + length), 0, types[Math.floor(rand() * 2)]]);
      t += length + 1 + Math.floor(rand() * spread);
    }
  }
  // Shuffle the rows and give them session ids in that shuffled order.
  for (let i = Sessions.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [Sessions[i], Sessions[j]] = [Sessions[j], Sessions[i]];
  }
  for (const row of Sessions) row[3] = ++id;
  return [{ Sessions }];
}
